 "content": "def transform(grid):
    out = [row[:] for row in grid]
    base = next((r for r, row in enumerate(grid) if any(v in (2, 8) for v in row)), None)
    if base is None:
        return out
    marks = [c for c, v in enumerate(grid[base]) if v in (2, 8)]
    if len(marks) >= 2:
        height = marks[1] - marks[0]
        for c in marks:
            for d in range(1, min(height, base + 1)):
                out[base-d][c] = 1
            if base-height >= 0:
                out[base-height][c] = grid[base][c]
    return out

if __name__ == '__main__':
